import * as express from 'express';

declare namespace gcipCloudFunctions {
  interface EventContext {
    /** ID of the event */
    eventId: string;
    /** Timestamp for when the event occured (ISO string) */
    timestamp: string;
    /** Type of event */
    eventType: string;
    /** Resource that triggered the event */
    resource: string;
    /** Key-value pairs that represent the values of wildcards in a database reference */
    params: { [option: string]: any }; // added by SDK, but may be {}
    /**
     * Type of authentication for the triggering action, valid value are: 'ADMIN', 'USER',
     * 'UNAUTHENTICATED'. Only available for database functions.
     */
    authType?: 'ADMIN' | 'USER' | 'UNAUTHENTICATED';
    /**
     * Firebase auth variable for the user whose action triggered the function. Field will be
     * null for unauthenticated users, and will not exist for admin users. Only available
     * for database functions.
     */
    auth?: {
      uid: string;
      token: object;
    };
  }

  interface Error {
    code: string;
    message: string;
    stack: string;
    toJSON(): object;
  }

  interface AdditionalUserInfo {
    providerId: string;
    profile?: any;
    username?: string;
    isNewUser: boolean;
  }

  interface AuthCredential {
    claims?: {[key: string]: any};
    idToken?: string;
    accessToken?: string;
    refreshToken?: string;
    expirationTime?: string;
    secret?: string;
    providerId: string;
    signInMethod: string;
  }

  interface AuthEventContext extends gcipCloudFunctions.EventContext {
    locale?: string;
    ipAddress: string;
    userAgent: string;
    additionalUserInfo?: AdditionalUserInfo;
    credential?: AuthCredential;
  }

  interface UserEventUpdateRequest {
    email?: string;
    emailVerified?: boolean;
    displayName?: string | null;
    photoURL?: string | null;
    disabled?: boolean;
    providerData?: Array<{
      uid: string;
      displayName?: string;
      email?: string;
      photoURL?: string;
      providerId: string;
    }>;
    multiFactor?: {
      enrolledFactors: gcipCloudFunctions.MultiFactorInfo[];
    };
    customClaims?: object;
    sessionClaims?: object;
    tenantId?: string | null;
  }

  interface AuthOptions {
    credentials?: {
      private_key: string;
      client_email: string;
      project_id: string;
    };
    serviceAccountId?: string;
    projectId?: string;
  }

  class Auth {
    constructor(options?: gcipCloudFunctions.AuthOptions);
    functions(): gcipCloudFunctions.Functions;
  }

  interface UserMetadata {
    lastSignInTime: string;
    creationTime: string;
    toJSON(): object;
  }

  interface UserInfo {
    uid: string;
    displayName: string;
    email: string;
    phoneNumber: string;
    photoURL: string;
    providerId: string;
    toJSON(): object;
  }

  interface MultiFactorInfo {
    uid: string;
    displayName?: string | null;
    enrollmentTime?: string | null;
    factorId: string;
    toJSON(): object;
  }

  interface PhoneMultiFactorInfo extends gcipCloudFunctions.MultiFactorInfo {
    phoneNumber: string;
  }

  interface UserRecord {
    uid: string;
    email: string;
    emailVerified: boolean;
    displayName: string;
    phoneNumber: string;
    photoURL: string;
    disabled: boolean;
    metadata: gcipCloudFunctions.UserMetadata;
    providerData: gcipCloudFunctions.UserInfo[];
    multiFactor?: {
      enrolledFactors: gcipCloudFunctions.PhoneMultiFactorInfo[];
    };
    passwordHash?: string;
    passwordSalt?: string;
    customClaims?: object;
    tokensValidAfterTime?: string;
    tenantId?: string | null;
    toJSON(): object;
  }

  type HttpFunction = (req: express.Request, res: express.Response) => void;

  type BeforeCreateHandlerCallback = (
    user: gcipCloudFunctions.UserRecord,
    context: gcipCloudFunctions.AuthEventContext,
  ) => gcipCloudFunctions.UserEventUpdateRequest | Promise<gcipCloudFunctions.UserEventUpdateRequest>;

  type BeforeSignInHandlerCallback = (
    user: gcipCloudFunctions.UserRecord,
    context: gcipCloudFunctions.AuthEventContext,
  ) => gcipCloudFunctions.UserEventUpdateRequest | Promise<gcipCloudFunctions.UserEventUpdateRequest>;

  interface Functions {
    beforeCreateHandler(
      callback: gcipCloudFunctions.BeforeCreateHandlerCallback,
      errCallback?: (error: gcipCloudFunctions.Error) => void,
    ): gcipCloudFunctions.HttpFunction;
    beforeSignInHandler(
      callback: gcipCloudFunctions.BeforeSignInHandlerCallback,
      errCallback?: (error: gcipCloudFunctions.Error) => void,
    ): gcipCloudFunctions.HttpFunction;
  }

  interface GoogleOAuthAccessToken {
    access_token: string;
    expires_in: number;
  }
}

declare namespace gcipCloudFunctions.https {
  class HttpsError {
    code: string;
    message: string;
    constructor(code: string, message?: string);
    toJSON(): object;
  }
}

declare module 'gcip-cloud-functions' {
}

/* tslint:disable:export-just-namespace */
export = gcipCloudFunctions;
/* tslint:enable:export-just-namespace */
